    result.reserve(sites.size());

    // Define CGAL types based on the internal namespace provided in the context
    typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
    typedef CGAL::Delaunay_triangulation_2<K> DT;
    typedef CGAL::Delaunay_triangulation_adaptation_traits_2<DT> AT;
    typedef CGAL::Delaunay_triangulation_caching_degeneracy_removal_policy_2<DT> AP;
    typedef CGAL::Voronoi_diagram_2<DT, AT, AP> VD;

    // Construct the Voronoi diagram from the input sites
    VD vd;
    for (const auto& site : sites) {
        vd.insert(K::Point_2(site.x(), site.y()));
    }

    // Iterate through all faces of the Voronoi diagram
    for (auto fit = vd.faces_begin(); fit != vd.faces_end(); ++fit) {
        std::vector<cg3::Point2d> cell;

        // A face is bounded if it has a finite number of vertices
        if (fit->is_unbounded()) {
            // Unbounded cells are typically skipped or handled specifically 
            // in this implementation's return type (vector of vertices)
            result.push_back(cell);
            continue;
        }

        // Use the circulator to traverse the edges of the cell
        VD::Ccb_halfedge_circulator hc = fit->incident_halfedges();
        VD::Ccb_halfedge_circulator done = hc;
        do {
            VD::Vertex_handle v = hc->source();
            if (v != nullptr) {
                cell.push_back(cg3::Point2d(CGAL::to_double(v->point().x()), CGAL::to_double(v->point().y())));
            }
            hc++;
        } while (hc != done);

        result.push_back(cell);
    }

    return result;

